    elsif k = 'payoff_dmg' then if combat_effect_v2_has(tu, blk, clk) then sbonus := sbonus + (blk->>'v')::numeric * ab; end if;
    elsif k = 'crit_add' then scrit := scrit + (blk->>'v')::numeric * ab;
